"""Independent review; unchanged lessons retain prior read proofs, not model confidence."""
import json,sys
from pathlib import Path
b=Path('tools/specialist-training/iteration-03');p=b/'math-review.json';reviews=json.loads(p.read_text())
proofs={
 'nt3-cube-difference':('Exactly(−1,−2),(2,1).','Factor with d=x−y and Q=x²+xy+y²>0. All d divide7. Negative d contradict Q>0. For d7, Q1 but completing the square gives Q=3(y+d/2)²+d²/4≥d²/4=49/4, impossible. For d1, Q=3y²+3y+1=7, hence(y+2)(y−1)=0: y=−2 or y=1, giving the two pairs. Direct cubes give−1−(−8)=7 and8−1=7. This covers every divisor and both signed solutions.'),
 'nt3-cube-difference-positive':('No positive integer pair.','All d=x−y divide9; Q>0 makes d positive. For d1, D=105 lies strictly between10² and11², so no integer y. For d3, D9 yields y=(−9±3)/6=−1 or−2, giving(2,−1),(1,−2), both outside the positive domain. For d9, D=12−243=−231<0. Negative divisors have negative Q and cannot work. Every case is rejected for an explicit reason.'),
 'nt3-cube-difference-zero':('All x=y in the integer domain; witness(1,1).','The factorization has(x−y)Q=0, with2Q=(x+y)²+x²+y². If Q0 then x=y=0; otherwise the zero product forces x=y. Conversely equality of the variables makes the cubes equal. Pair(1,1) verifies1³−1³=0 and belongs to the domain.'),
 'nt3-val-cube-negative':('Exactly(−2,−1),(1,2).','Swapping the coordinates turns u³−v³=−7 into the independently solved difference7. Thus the complete pairs are the reversals of(−1,−2),(2,1). Direct checking gives−8−(−1)=−7 and1−8=−7. The signed-divisor proof transfers bijectively, not by a finite sample.'),
 'nt3-val-cube-double-root':('Exactly(1,−1).','Positive quotient forces positive d dividing2. At d1, D=24−3=21 is between4² and5², so no integer y. At d2, D=12−12=0: both signs produce the same root y=−1,x1, counted once. Negative d cannot have positive Q. The original cubes give1−(−1)=2.'),
 'nt3-val-cube-impossible':('No integer pair.','Independently of the factor-based implementation, enumerate all9 residue classes modulo9: cubes have remainders0,1,8. Differences of these remainders have only0,1,2,7,8, never6. Thus the original equation is impossible for every integer pair. This universal residue proof confirms the app’s full divisor/root rejection argument.'),
 'nt3-val-cube-positive-zero':('All d=h>0; explicit witness(1,1).','Equality of cubes forces equality of integer bases through the positive quadratic factor, or the zero-factor case where both are0. The latter is excluded by positivity. Conversely every equal positive pair works. Pair(1,1) is a concrete legal witness, and every positive common value is retained.'),
 'nt3-factorial-zeros':('24 trailing zero digits.','The multiples of5 in1..100 contribute20 factors5; multiples25 contribute4 additional factors, and125 exceeds100. Thus exactly24 factors5. At every power level there are at least as many multiples of2 as5, so24 pairs2·5 can be formed and a25th cannot. This proves exactly24 zeros, rather than estimating the number of decimal digits.'),
 'nt3-factorial-prime-power':('k=22.','In50!, factors3 occur16+5+1=22 times at levels3,9,27;81 exceeds50. A term divisible3^e contributes once at each of the e levels, so this is exact. Therefore3^22 divides50!, whereas3^23 does not, proving maximality.'),
 'nt3-factorial-quotient':('k=2.','The quotient counts10-element subsets of20 distinct objects: every such group is counted10!10! times among20! orders, hence an integer. It equals184756=4·46189, with46189 odd. Independently the exponent of2 in20! is10+5+2+1=18; each10! contributes5+2+1=8, so the quotient has exponent18−8−8=2. Both direct factorization and level counts prove maximality.'),
 'nt3-val-factorial-boundary':('0 trailing zero digits.','The defined empty factorial0! equals1, whose decimal representation ends in1. There are no factors5 and hence no factors10. The corrected actual explanation explicitly uses0!=1 and does not display a nonexistent sequence1,2,…,0.'),
 'nt3-val-factorial-many-levels':('31 trailing zero digits.','The multiples of5,25,125 up to125 number25,5,1, giving exactly31 factors5. The next level625 exceeds125. Factors2 are at least as numerous at every level, so all31 factors5 can be paired and no32nd pair exists.'),
 'nt3-val-factorial-rename':('j=22.','The exact count in50! at prime3 is16+5+1=22. In the returned proof i counts power levels and j is the unknown maximal exponent, so the symbols have distinct roles.3^22 divides and3^23 does not.'),
 'nt3-val-factorial-small-quotient':('t=2.','12!/(5!7!) counts5-element subsets of12, hence is an integer. Its exact value is792=9·88, with88 not divisible3. Independently the numerator exponent is4+1=5 and the denominators contribute1 and2, so the exponent is5−1−2=2. No further factor3 remains.'),
 'nt3-val-factorial-empty-power':('k=0.','1!=1 is divisible2^0=1 and is not divisible2^1=2. Hence the maximal nonnegative exponent is0. The returned proof uses the fact2 exceeds every factor of1!, without a false conditional about1 being0.'),
}
target=sys.argv[1] if len(sys.argv)>1 else 'v225'
old_version='v225' if target=='v227' else 'v222'
for phase,old in [(f'development-number-theory-final-{target}',f'development-number-theory-final-{old_version}'),(f'validation-number-theory-final-{target}',f'validation-number-theory-final-{old_version}')]:
 previous={r['id']:r for r in map(json.loads,(b/(old+'.jsonl')).read_text().splitlines())}
 for r in map(json.loads,(b/(phase+'.jsonl')).read_text().splitlines()):
  ident=r['id'];assert r['body']['solution']['status']=='ready'
  if ident in proofs:
   answer,proof=proofs[ident];review={'independentAnswer':answer,'independentDerivation':proof,'mathematics':'pass','completeness':'pass','explanation':'pass','conclusionCorrect':True,'rubric':{'correctness':40,'completeness':20,'clarity':14,'method':10,'formatting':10,'verificationOrUncertainty':5},'reviewScope':'Actual full steps and hints read independently; exact arithmetic and counting proof above. Development or exposed-family diagnostic only. No human satisfaction or held-out claim.'}
  else:
   assert r['body']['solution']['lesson']==previous[ident]['body']['solution']['lesson'], 'Changed actual lesson requires a fresh read: '+ident
   review=reviews[old+'/'+ident].copy();review['reviewScope']='Fresh actual API execution. Complete lesson equality checked against the previously read and independently proved answer; no change to captured mathematical text. Exposed families, not held-out.'
  review['presentationLimits']='Schema, KaTeX, all-field Vietnamese and numeric assertion audits clean. Page-only browser and standalone compilation are separately reported.';reviews[phase+'/'+ident]=review
if target=='v227':
 for r in map(json.loads,(b/'baseline-number-theory-cubes.jsonl').read_text().splitlines()):
  ident=r['id'];answer,proof=proofs[ident];assert r['body']['solution']['status']=='failed'
  reviews['baseline-number-theory-cubes/'+ident]={'independentAnswer':answer,'independentDerivation':proof,'mathematics':'unverified','completeness':'fail','explanation':'fail','conclusionCorrect':False,'failureAnalysis':'Actual baseline returned a controlled failure under30seconds; no complete proof. Repaired with cube factorization, a proved finite box, all signed divisors and explicit root/domain rejection reasons.','reviewScope':'Actual baseline, unchanged raw output. No model self-check used as mathematical evidence.'}
for phase in ['baseline-number-theory-prime-exponents','development-number-theory-prime-exponents-v223','development-number-theory-prime-exponents-v224','validation-number-theory-prime-exponents-v224']:
 for r in map(json.loads,(b/(phase+'.jsonl')).read_text().splitlines()):
  ident=r['id'];answer,proof=proofs[ident];ready=r['body']['solution']['status']=='ready'
  reviews[phase+'/'+ident]={'independentAnswer':answer,'independentDerivation':proof,'mathematics':'pass' if ready else 'unverified','completeness':'pass' if ready else 'fail','explanation':'pass' if ready else 'fail','conclusionCorrect':ready,'failureAnalysis':None if ready else ('Trailing-digit statement was routed as algebra and the valid NT certificate rejected; fixed Number Theory routing and added a full-pipeline no-inference regression.' if phase.endswith('v223') else 'Actual solver returned a controlled failure; raw failure and measured latency retained. Repaired with bounded prime-factor counting and an independent per-integer checker.'),'reviewScope':'Actual development capture; zero/one-factorial v224 wording is awkward and was improved in final v225. No held-out or human claim.'}
p.write_text(json.dumps(reviews,ensure_ascii=False,indent=2)+'\n')
print('Reviewed final actual development and diagnostic answers; retained earlier failures.')
